import {ordinaryConversation,isQuestion} from './conversation.mjs';
import {playerContributionLine,legacyPlayerLine,requiresPlayerContribution,contributionRule as playerOpeningRule} from './player-contribution.mjs';
export {contributionRule as playerOpeningRule,contributionRepairRule as openingRepairRule,assertPlayerContributions as assertPlayerOpening} from './player-contribution.mjs';
// First-line interpretation adapted from Venus University scenePrompt.ts, ec8f7cee4fd9236e3dbcdc2e4683afba3acab748. AGPL-3.0-only; see LICENSE.
export const requiresPlayerOpening=c=>requiresPlayerContribution(c);
export const playerOpeningLine=(line,c)=>requiresPlayerOpening(c)&&(playerContributionLine(line)||legacyPlayerLine(line));
const words=t=>String(t).normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().match(/[\p{L}']{3,}/gu)||[],stop=new Set('you your yours the that this with from than then and but for are was were have has had would should could will can may did does not dont don\'t never its her his their them she him they about into more rather just really very some something tell telling say saying ask asking enjoy enjoyed like liked'.split(' ')),negative=/\b(?:no|not|never|don['’]t|won['’]t|can['’]t|isn['’]t|aren['’]t|cannot|declin\w*|refus\w*|off duty|outside(?: of)? work)\b/iu;
const fail=message=>{throw Object.assign(Error(message),{lintCheck:'player-opening',safeRepair:playerOpeningRule,openingOnly:true});};
const speech=new Set('say tell ask reply answer whisper shout explain admit confess tease flirt joke kid compliment decline refuse respond remark acknowledge thank express mention clarify inquire question check agree reassure'.split(' ')),verb=t=>/^\s*(?:I|You)\s+(?:(?:lightly|gently|mildly|quietly|directly|playfully|simply)\s+)?(\p{L}+)\b/iu.exec(t)?.[1].toLowerCase(),aliases=v=>['set','put','place'].includes(v)?['set','put','place']:[v];
const physical=new Set('set put place hold lift reach touch kiss smile smirk nod laugh blush grin point gesture lean walk leave accept promise'.split(' '));
export function openingAct(c){const input=String(c.playerAction||''),v=verb(input),m=/^\s*I\s+((?:(?:lightly|gently|mildly|quietly|directly|playfully|simply)\s+)?\p{L}+)\b/iu.exec(input);return m&&(speech.has(v)||physical.has(v))?m[1].toLowerCase():isQuestion(input)?'ask':'say';}
export function assertPlayerMeaning(lines,c,pack={actors:[]},{combined=false}={}){
 if(!requiresPlayerOpening(c))return;const line=lines?.[0],input=String(c.playerAction),text=line?.text||'';if(line?.speaker!==''||!/^You\b/u.test(text))fail('Player indirect contribution needs second-person narration');if(!combined&&(text.length>1000||/["“”]/u.test(text)||/(?:^|\s)I(?:\s|['’])/u.test(text)))fail('Player opening must be indirect narrator wording in one entry');
 const first=verb(text),submitted=verb(input);if(!first||!speech.has(first)&&!aliases(first).some(v=>words(input).includes(v)))fail('Player opening adds an unsubmitted leading action');if(physical.has(submitted)&&!aliases(submitted).some(v=>words(text).includes(v)))fail('Player opening omits the submitted physical action');if(!combined&&/[.!?]\s+(?!You\b)/u.test(text))fail('Player opening includes a separate NPC or scene reaction');
 const anchors=[...new Set(words(input).filter(w=>!stop.has(w)).map(w=>w.slice(0,4)))],t=new Set(words(text).map(w=>w.slice(0,4)));if(anchors.filter(w=>t.has(w)).length<Math.min(2,anchors.length))fail('Player opening omits the submitted meaning');
 if(negative.test(input)&&!negative.test(text))fail('Player opening loses negation or refusal');if(/\bteas\w*\b/iu.test(input)&&!/\b(?:teas\w*|jok\w*|kid\w*)\b/iu.test(text))fail('Player opening loses teasing intent');if(/\bflirt\w*\b/iu.test(input)&&!/\bflirt\w*\b/iu.test(text))fail('Player opening loses expressed flirtation');
 if(/\blightly\s+flirt\b/iu.test(input)&&!/\b(?:light\w*|gentl\w*|mild\w*|a little)\b/iu.test(text))fail('Player opening changes the degree of flirtation');
 for(const action of ['point','gesture','lean','smile','smirk','nod','laugh','blush','grin','kiss','touch','reach','walk','leave','accept','promise'])if(new RegExp(`\\b(?:you |and |while |as you )${action}\\w*\\b`,'iu').test(text)&&!new RegExp(`\\b${action}\\w*\\b`,'iu').test(input))fail('Player opening invents an unsubmitted action');
 for(const a of pack.actors||[]){if(a.id===pack.playerId)continue;const name=words(a.name?.split(' ')[0]||'')[0];if(name&&words(input).includes(name)&&!words(text).includes(name))fail('Player opening loses its named referent');}
}
